var _markdown = "\n\n# Custom Rendering [#custom-rendering]\n\n## Custom Tag Rendering [#custom-tag-rendering]\n\n```tsx\nconst CustomTag = ({ tag, onDelete }) => (\n  <TouchableOpacity \n    style={styles.customTag}\n    onPress={() => console.log('Tag pressed:', tag)}\n  >\n    <Text style={styles.tagEmoji}>✨</Text>\n    <Text style={styles.tagText}>{tag}</Text>\n    <TouchableOpacity \n      style={styles.deleteButton} \n      onPress={onDelete}\n    >\n      <Text style={styles.deleteText}>×</Text>\n    </TouchableOpacity>\n  </TouchableOpacity>\n);\n\n<TagInput\n  tags={tags}\n  updateState={updateState}\n  renderTag={(tag, index, onDelete) => (\n    <CustomTag tag={tag} onDelete={onDelete} />\n  )}\n/>\n```\n\n## Custom Delete Button [#custom-delete-button]\n\n```tsx\nconst CustomDeleteButton = (onDelete, tag) => (\n  <TouchableOpacity \n    style={styles.deleteBtn}\n    onPress={onDelete}\n  >\n    <Text style={styles.deleteIcon}>🗑️</Text>\n  </TouchableOpacity>\n);\n\n<TagInput\n  tags={tags}\n  updateState={updateState}\n  renderDeleteButton={CustomDeleteButton}\n/>\n```\n\n## Custom Input Rendering [#custom-input-rendering]\n\n```tsx\nconst CustomInput = ({ value, onChangeText, ...props }) => (\n  <TextInput\n    {...props}\n    value={value}\n    onChangeText={onChangeText}\n    style={styles.customInput}\n    placeholderTextColor=\"#999\"\n  />\n);\n\n<TagInput\n  tags={tags}\n  updateState={updateState}\n  renderInput={(inputProps) => (\n    <CustomInput {...inputProps} />\n  )}\n/>\n```\n\n## Custom Container [#custom-container]\n\n```tsx\nconst CustomContainer = ({ children }) => (\n  <View style={styles.customContainer}>\n    <Text style={styles.label}>Custom Tags Input</Text>\n    {children}\n    <Text style={styles.helper}>\n      Press space or comma to add a tag\n    </Text>\n  </View>\n);\n\n<TagInput\n  tags={tags}\n  updateState={updateState}\n  renderContainer={(children) => (\n    <CustomContainer>{children}</CustomContainer>\n  )}\n/>\n```\n\n## Styling Examples [#styling-examples]\n\n```tsx\nconst styles = StyleSheet.create({\n  customTag: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    backgroundColor: '#007AFF',\n    borderRadius: 20,\n    paddingVertical: 8,\n    paddingHorizontal: 12,\n    margin: 4,\n  },\n  tagEmoji: {\n    fontSize: 14,\n    marginRight: 6,\n  },\n  tagText: {\n    color: '#FFFFFF',\n    fontSize: 14,\n    fontWeight: '600',\n  },\n  deleteButton: {\n    marginLeft: 8,\n    padding: 4,\n  },\n  deleteText: {\n    color: '#FFFFFF',\n    fontSize: 16,\n    fontWeight: 'bold',\n  },\n  customInput: {\n    height: 40,\n    borderColor: '#E0E0E0',\n    borderWidth: 1,\n    borderRadius: 8,\n    paddingHorizontal: 12,\n    fontSize: 16,\n  },\n  customContainer: {\n    backgroundColor: '#F5F5F5',\n    padding: 16,\n    borderRadius: 12,\n  },\n  label: {\n    fontSize: 16,\n    fontWeight: '600',\n    marginBottom: 8,\n  },\n  helper: {\n    fontSize: 12,\n    color: '#666',\n    marginTop: 8,\n  },\n});\n```\n";
